// MARK: - F10 §4.5: the page's own content does not collide

/// F5's class, not F5's row: every labelled leaf and control the real
/// page has on screen, signed in and at rest, in portrait and landscape.
/// No two overlap (each inset by 1 pt, F5 §9's rule) and none leaves the
/// web view sideways. Shown to fail by removing the chip style's install:
/// the sweep names F5's pair without being pointed at the instance bar.
func testThePagesOwnContentDoesNotCollide() async throws {
    let run = try await signedInRun()
    for (name, look) in [("portrait", run.portraitPage), ("landscape", run.landscapePage)] {
        let page = try XCTUnwrap(look, "\(name): the page was read")
        let line = "PAGE-SWEEP \(name): web=\(page.web) items=\(page.items.count)"
        print(line + " " + describe(page.items))
        add(XCTAttachment(string: line + "\n" + describe(page.items)))
        XCTAssertGreaterThanOrEqual(page.items.count, 5, "\(name): the sweep read the page: \(line)")
        for problem in collisions(page) { XCTFail("\(name): \(problem)") }
    }
}

/// The page as the sweep sees it: its web view's frame and every item on
/// screen.
private struct PageLook {
    let items: [Chip]
    let web: CGRect
}

/// Every labelled leaf and control of the page (`labelledItems`, F5's
/// rule) that is on screen: under 2 pt on either axis is visually hidden
/// text, and anything outside the web view's frame is scrolled away.
private func lookAtPage(_ app: XCUIApplication) throws -> PageLook {
    let web = app.webViews.firstMatch
    let frame = web.frame
    let items = try labelledItems(web).filter {
        $0.frame.width >= 2 && $0.frame.height >= 2 && $0.frame.intersects(frame)
    }
    return PageLook(items: items, web: frame)
}

/// Every overlapping pair and every item out of the web view sideways, as
/// sentences that name both frames.
private func collisions(_ page: PageLook) -> [String] {
    var problems: [String] = []
    let items = page.items
    for (i, a) in items.enumerated() {
        for b in items[(i + 1)...] where !a.frame.insetBy(dx: 1, dy: 1).intersection(b.frame.insetBy(dx: 1, dy: 1)).isEmpty {
            problems.append("\(describe([a])) and \(describe([b])) overlap")
        }
        if a.frame.minX < page.web.minX - 0.5 || a.frame.maxX > page.web.maxX + 0.5 {
            problems.append("\(describe([a])) leaves the web view \(page.web) sideways")
        }
    }
    return problems
}

