private func lookAtPage(_ app: XCUIApplication) throws -> PageLook {
    let web = app.webViews.firstMatch
    let frame = web.frame
    let controls: [XCUIElement.ElementType] = [.button, .link, .popUpButton, .menuButton,
                                               .textField, .textView, .searchField]
    var found: [(Chip, XCUIElement.ElementType)] = []
    func labelled(_ node: XCUIElementSnapshot) -> Bool {
        node.children.contains { !$0.label.isEmpty || labelled($0) }
    }
    func walk(_ node: XCUIElementSnapshot, clip: CGRect) {
        for child in node.children where child.elementType != .scrollBar {
            let leaf = controls.contains(child.elementType) || (!child.label.isEmpty && !labelled(child))
