/// Every labelled leaf and control of the page (F5's rule) that draws
/// something: a labelled `.other` is a region (a live region, a scroll
/// bar), not content. Each frame is clipped by its scrolling ancestors;
/// dropped are items under 2 pt on either axis once clipped (visually
/// hidden text, or scrolled away) and a same-label item at or inside
/// another's frame (a field and its placeholder, a control and its icon).
///
/// The tree has no z-order, so an overlap in it is not yet a collision:
/// content scrolled under the page's sticky header overlaps the header's
/// buttons there, as does a chip scrolled out of the instance bar under
/// the button beside it. A pair is a collision when both are hittable,
/// i.e. each is on top at its own centre: both drawn, one over the other.
private func lookAtPage(_ app: XCUIApplication) throws -> PageLook {
    let web = app.webViews.firstMatch
    let frame = web.frame
    let controls: [XCUIElement.ElementType] = [.button, .link, .popUpButton, .menuButton,
                                               .textField, .textView, .searchField]
    struct Item { let chip: Chip; let raw: CGRect; let type: XCUIElement.ElementType }
    var found: [Item] = []
    func labelled(_ node: XCUIElementSnapshot) -> Bool {
        node.children.contains { !$0.label.isEmpty || labelled($0) }
    }
    func walk(_ node: XCUIElementSnapshot, clip: CGRect) {
        for child in node.children {
            let leaf = controls.contains(child.elementType) || (!child.label.isEmpty && !labelled(child))
            if leaf {
                let shown = child.frame.intersection(clip)
                if !child.label.isEmpty, child.elementType != .other, Self.pageSweepExempt[child.label] == nil,
                   !shown.isNull, shown.width >= 2, shown.height >= 2 {
                    found.append(Item(chip: Chip(label: child.label, frame: shown), raw: child.frame,
                                      type: child.elementType))
                }
            } else {
                walk(child, clip: child.elementType == .scrollView ? clip.intersection(child.frame) : clip)
            }
        }
    }
    walk(try web.snapshot(), clip: frame)
    var kept: [Item] = []
    for item in found where !kept.contains(where: {
        $0.chip.label == item.chip.label && ($0.chip.frame.contains(item.chip.frame) || item.chip.frame.contains($0.chip.frame))
    }) {
        kept.append(item)
    }

    func hittable(_ item: Item) -> Bool {
        web.descendants(matching: item.type).matching(NSPredicate(format: "label == %@", item.chip.label))
            .allElementsBoundByIndex.first { $0.frame == item.raw }?.isHittable ?? false
    }
    var collisions: [String] = [], covered: [String] = []
    for (i, a) in kept.enumerated() {
        for b in kept[(i + 1)...]
        where !a.chip.frame.insetBy(dx: 1, dy: 1).intersection(b.chip.frame.insetBy(dx: 1, dy: 1)).isEmpty {
            let (ha, hb) = (hittable(a), hittable(b))
            let pair = "\(describe([a.chip])) [\(ha ? "on top" : "hidden")] and \(describe([b.chip])) [\(hb ? "on top" : "hidden")]"
            if ha && hb { collisions.append(pair + " overlap") } else { covered.append(pair) }
        }
    }
    return PageLook(items: kept.map(\.chip), web: frame,
                    types: kept.map { "\(describe([$0.chip])) [\($0.type.rawValue)]" },
                    collisions: collisions, covered: covered)
}

